    graph=[{'@type':'WebPage','url':url,'name':p['title'],'description':p['desc'],'inLanguage':'ar','dateModified':DATE},{'@type':'Article','headline':p['title'],'description':p['desc'],'inLanguage':'ar','datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'منصة روافد'},'publisher':{'@type':'Organization','name':'منصة روافد'},'citation':[SOURCES[i][1] for i in p['sources']]},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'الرئيسية','item':BASE+'/'},{'@type':'ListItem','position':2,'name':'ذوو الاحتياجات الخاصة','item':BASE+'/special-needs/'},{'@type':'ListItem','position':3,'name':'المراجع الأساسية','item':BASE+'/special-needs/reference/'},{'@type':'ListItem','position':4,'name':p['title'],'item':url}]}]
    return json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')
